#requires -Version 5.1
[CmdletBinding()]
param([Parameter(Mandatory)][string]$Plan,[string]$PgBin='C:\Program Files\PostgreSQL\19\bin')
Set-StrictMode -Version Latest
$ErrorActionPreference='Stop';$ProgressPreference='SilentlyContinue'
function Read-Hidden([string]$Label){$s=Read-Host -Prompt $Label -AsSecureString;try{if($s.Length-eq 0){throw 'Value cannot be empty.'};$p=[Runtime.InteropServices.Marshal]::SecureStringToBSTR($s);try{[Runtime.InteropServices.Marshal]::PtrToStringBSTR($p)}finally{[Runtime.InteropServices.Marshal]::ZeroFreeBSTR($p)}}finally{$s.Dispose()}}
function Send([Net.Http.HttpMethod]$Method,[string]$Path,[object]$Payload,[switch]$Rpc){$q=[Net.Http.HttpRequestMessage]::new($Method,$Path);try{if($Rpc){$q.Headers.Add('Content-Profile','reivro_checks_api')};$q.Content=[Net.Http.StringContent]::new((ConvertTo-Json $Payload -Depth 20 -Compress),[Text.Encoding]::UTF8,'application/json');$x=$script:client.SendAsync($q).GetAwaiter().GetResult();try{[pscustomobject]@{Status=[int]$x.StatusCode;Body=$x.Content.ReadAsStringAsync().GetAwaiter().GetResult()}}finally{$x.Dispose()}}finally{$q.Dispose()}}
function Invoke-PsqlJson([string]$Sql,[hashtable]$Extra){$oldPassword=[Environment]::GetEnvironmentVariable('PGPASSWORD','Process');$oldCert=[Environment]::GetEnvironmentVariable('PGSSLROOTCERT','Process');try{$env:PGPASSWORD=$script:dbPassword;$env:PGSSLROOTCERT=$script:ca;$args=@('-X','-w','-qAt','-v','ON_ERROR_STOP=1','-d','host=aws-1-us-west-1.pooler.supabase.com port=5432 user=postgres.lbklqqqbmeyseeccdqog dbname=postgres sslmode=verify-full','-v',"repository_id=$($script:f.repository_id)",'-v',"contract_id=$($script:f.contract_id)",'-v',"submission_id=$($script:f.submission_id)",'-v',"digest=$($script:f.digest)",'-v',"base_sha=$($script:f.base_sha)",'-v',"head_sha=$($script:f.head_sha)");foreach($k in $Extra.Keys){$args+=@('-v',"$k=$($Extra[$k])")};$args+=@('-f',$Sql);$o=& $script:psql @args;if($LASTEXITCODE-ne 0){throw "psql exited $LASTEXITCODE"};$lines=@($o|Where-Object{$_-match'^\{'});if($lines.Count-ne 1){throw 'Expected exactly one sanitized reconciliation record.'};$lines[0]|ConvertFrom-Json}finally{if($null-eq$oldPassword){Remove-Item Env:PGPASSWORD -ErrorAction SilentlyContinue}else{$env:PGPASSWORD=$oldPassword};if($null-eq$oldCert){Remove-Item Env:PGSSLROOTCERT -ErrorAction SilentlyContinue}else{$env:PGSSLROOTCERT=$oldCert}}}
$client=$handler=$key=$email=$password=$session=$dbPassword=$approval=$null;$stage='plan';$writeAttempted=$false
try{
 $pre=Join-Path $PSScriptRoot 'preflight_staging_expired_lease.sql';$post=Join-Path $PSScriptRoot 'postcheck_staging_recovered_lease.sql';$cert=Join-Path $HOME 'Downloads\prod-ca-2021.crt'
 foreach($p in @($Plan,$pre,$post,$cert)){if(-not(Test-Path -LiteralPath $p)){throw "Required path missing: $p"}}
 $f=Get-Content -LiteralPath $Plan -Raw|ConvertFrom-Json
 if($f.staging_ref-cne'lbklqqqbmeyseeccdqog'-or[guid]$f.agent_id-ne[guid]'0dae2b29-adaa-48b6-9a96-e9ac646b2a7a'-or[guid]$f.contract_id-eq[guid]::Empty-or[guid]$f.submission_id-eq[guid]::Empty-or[long]$f.repository_id-le 0-or[string]$f.base_sha-cne'07fc0b907d3aa9659ea7541f80acf6c18586e645'-or[string]$f.head_sha-cne'e0d50dd239f8c8c3c39df84187741009f7496d09'-or[string]$f.digest-cnotmatch'^[0-9a-f]{64}$'){throw 'Private plan differs from approved fixture.'}
 $psql=(Get-Command(Join-Path $PgBin 'psql.exe')-CommandType Application).Source;if((&$psql --version)-notmatch'\s19\.\d+(?:\s|$)'){throw 'Use PostgreSQL 19 psql.'};$ca=(Resolve-Path -LiteralPath $cert).Path
 $key=(Read-Hidden 'Staging default publishable key').Trim();$email=(Read-Hidden 'Worker A staging email').Trim();$password=Read-Hidden 'Worker A staging password';$dbPassword=Read-Hidden 'Staging PostgreSQL password for reconciliation';if($key-cnotmatch'^sb_publishable_[A-Za-z0-9_-]+$'){throw 'Invalid publishable key.'}
 $stage='expired lease preflight';$scope=Invoke-PsqlJson $pre @{};$workerId=[guid]$scope.worker_id;$oldRun=[guid]$scope.run_id;$oldAttempt=[guid]$scope.old_attempt_id;$oldFence=[int]$scope.old_fence;if($workerId-eq[guid]::Empty-or$oldRun-eq[guid]::Empty-or$oldAttempt-eq[guid]::Empty-or$oldFence-ne 1){throw 'Expired lease preflight failed.'};Write-Output 'PASS expired lease confirmed by PostgreSQL clock'
 Add-Type -AssemblyName System.Net.Http;[Net.ServicePointManager]::SecurityProtocol=[Net.ServicePointManager]::SecurityProtocol-bor[Net.SecurityProtocolType]::Tls12;$handler=[Net.Http.HttpClientHandler]::new();$handler.AllowAutoRedirect=$false;$handler.UseCookies=$false;$client=[Net.Http.HttpClient]::new($handler);$client.BaseAddress=[uri]'https://lbklqqqbmeyseeccdqog.supabase.co';$client.Timeout=[TimeSpan]::FromSeconds(15);$client.DefaultRequestHeaders.Add('apikey',$key);$key=$null
 $stage='worker login';$x=Send ([Net.Http.HttpMethod]::Post) '/auth/v1/token?grant_type=password' @{email=$email;password=$password};if($x.Status-lt 200-or$x.Status-ge 300){throw "Login HTTP $($x.Status)"};$session=$x.Body|ConvertFrom-Json;if($session.user.id-cne$workerId.ToString()){throw 'Unexpected Worker identity.'};$client.DefaultRequestHeaders.Authorization=[Net.Http.Headers.AuthenticationHeaderValue]::new('Bearer',$session.access_token);$email=$password=$session=$null;Write-Output 'PASS Worker A Auth identity'
 $stage='authorization';$approval=Read-Host 'Type STAGING-EXPIRED-LEASE-RECOVERY-APPROVED to execute only the authorized recovery';if($approval-cne'STAGING-EXPIRED-LEASE-RECOVERY-APPROVED'){throw 'Lease recovery not confirmed.'}
 $request=@{repository_id=[long]$f.repository_id;installation_id=[long]$scope.installation_id;repository=[string]$scope.repository;base_ref=[string]$scope.base_ref;id=[string]$f.submission_id;delivery=[string]$f.submission_id;pr=1;base_sha=[string]$f.base_sha;head_sha=[string]$f.head_sha;digest=[string]$f.digest;verifier='task-completion-v1'}
 $stage='lease recovery';$writeAttempted=$true;$x=Send ([Net.Http.HttpMethod]::Post) '/rest/v1/rpc/task_dispatch' @{action='claim';request=$request} -Rpc;if($x.Status-lt 200-or$x.Status-ge 300){throw "Recovery HTTP $($x.Status)"};$claim=$x.Body|ConvertFrom-Json
 $stage='recovery reconciliation';$saved=Invoke-PsqlJson $post @{worker_id=$workerId;old_run_id=$oldRun;old_attempt_id=$oldAttempt};if(-not[bool]$saved.all_checks_pass){throw 'Persisted recovery state failed reconciliation.'};if([guid]$saved.run_id-ne$oldRun-or[guid]$saved.attempt_id-eq$oldAttempt-or[int]$saved.fence-ne 2){throw 'Recovered lease identity or fence mismatch.'};if([guid]$claim.run_id-ne$oldRun-or[guid]$claim.attempt_id-ne[guid]$saved.attempt_id-or[int]$claim.fence-ne 2){throw 'Recovery response and persisted lease differ.'};Write-Output 'PASS expired lease recovered with fence 2'
 $stage='stale fence denial';$stale=@{repository_id=[long]$f.repository_id;installation_id=[long]$scope.installation_id;id=[string]$f.submission_id;run_id=$oldRun.ToString();attempt_id=$oldAttempt.ToString();fence=$oldFence};$x=Send ([Net.Http.HttpMethod]::Post) '/rest/v1/rpc/task_dispatch' @{action='renew';request=$stale} -Rpc;if($x.Status-lt 400-or$x.Status-ge 500){throw 'Stale fence was not rejected as a client authorization error.'};$afterDenial=Invoke-PsqlJson $post @{worker_id=$workerId;old_run_id=$oldRun;old_attempt_id=$oldAttempt};if(-not[bool]$afterDenial.all_checks_pass-or[guid]$afterDenial.attempt_id-ne[guid]$saved.attempt_id-or[int]$afterDenial.fence-ne 2){throw 'Stale-fence probe changed persisted state.'};Write-Output 'PASS stale fence 1 denied with no durable effect';Write-Output 'EXPIRED_LEASE_RECOVERED_NO_EXECUTION'
}catch{[Console]::Error.WriteLine("FAIL $stage");if($writeAttempted){[Console]::Error.WriteLine('Do not retry. Run read-only reconciliation first.')};exit 1}finally{$key=$email=$password=$session=$dbPassword=$approval=$claim=$afterDenial=$x=$null;Remove-Item Env:PGPASSWORD,Env:PGSSLROOTCERT -ErrorAction SilentlyContinue;if($null-ne$client){$client.DefaultRequestHeaders.Authorization=$null;$client.Dispose()}elseif($null-ne$handler){$handler.Dispose()}}
